// H-MCP's catalogue preflight. The fixture is generated by the same
// agentcc-catalog command as CN30a, with no URL variables and one fixed mock.
import { execFileSync } from 'node:child_process';
import { readFileSync, realpathSync, statSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { isDeepStrictEqual } from 'node:util';
import { parse } from 'yaml';
import { inspectManagedMock, requireSafe, containerEnvironment, type Container } from './managed-mock';
import { MCP_STATE_KEY, PROFILE_RUNS_MCP_MOCK, walkGatewayProfile } from './profile';
import { MCP_MOCK } from './public-network';

const root = fileURLToPath(new URL('../../', import.meta.url));
const source = `${root}e2e/stack/mcp-mock/catalog/apps/e2e-echo`;
const provider = () => parse(readFileSync(`${source}/providers/key.yaml`, 'utf8'));
const app = () => parse(readFileSync(`${source}/app.yaml`, 'utf8'));

export function validateMcpCatalog(bundle: any): void {
  const expected = provider();
  requireSafe(expected.transport.url === MCP_MOCK.catalogUrl && !expected.transport.urlVariables &&
    expected.kind === 'vendor_mcp' && expected.auth.kind === 'api_key', 'MCP catalog upstream is not the fixed mock');
  requireSafe(bundle?.schema === 'connector-catalog-bundle/v1' &&
    isDeepStrictEqual(bundle.apps, [app()]) && isDeepStrictEqual(bundle.providers, [expected]) &&
    Array.isArray(bundle.platforms) && bundle.platforms.length === 0,
  'MCP catalog is not the generated single-mock fixture');
}

export function validateMcpAppMounts(container: Container): void {
  const env = containerEnvironment(container);
  requireSafe(env.AGENTCC_MCP_STATE_KEYS === MCP_STATE_KEY && env.SSL_CERT_FILE === '/opt/e2e/mcp/ca.pem',
    'MCP state sealing or TLS trust differs from the test profile');
  for (const [destination, source] of [
    ['/opt/e2e/mcp/catalog', `${root}e2e/.mcp/catalog`],
    ['/app/backend/agentcc/connector_catalog/catalog.json', `${root}e2e/.mcp/catalog/dist/catalog.json`],
    ['/opt/e2e/mcp/ca.pem', `${root}e2e/.mcp/ca.pem`],
  ]) {
    const mounts = container.Mounts.filter(m => m.Destination === destination);
    requireSafe(mounts.length === 1 && mounts[0].Type === 'bind' && !mounts[0].RW &&
      realpathSync(mounts[0].Source) === realpathSync(source), 'MCP catalog or trust mount is not the built fixture');
    requireSafe(statSync(source).mtimeMs <= Date.parse(container.State.StartedAt), 'MCP fixture changed after startup');
  }
}

/** Before any connector add or org-server seed: attest the real local stack,
 * both catalogue readers, the generated bundle, and normal TLS verification. */
export function inspectMcpCatalog() {
  requireSafe(PROFILE_RUNS_MCP_MOCK[walkGatewayProfile()], 'MCP catalog requires a profile that runs the MCP mock (mcp, mcp-signin)');
  const receipt = inspectManagedMock();
  const ids = execFileSync(`${root}bin/e2e`, ['compose', 'ps', '-q', 'app'], { encoding: 'utf8', timeout: 15_000 })
    .trim().split(/\s+/);
  requireSafe(ids.length === 1 && /^[a-f0-9]{12,64}$/.test(ids[0]), 'MCP app container is ambiguous');
  const containers: Container[] = JSON.parse(execFileSync('docker', ['inspect', ids[0]], { encoding: 'utf8', timeout: 15_000 }));
  requireSafe(containers.length === 1, 'MCP app container is ambiguous');
  validateMcpAppMounts(containers[0]);
  const bundle = JSON.parse(readFileSync(`${root}e2e/.mcp/catalog/dist/catalog.json`, 'utf8'));
  validateMcpCatalog(bundle);
  return { ...receipt, catalogVersion: bundle.version, catalogSha: bundle.sha256 };
}
